-- privacy (WP-25; 02-database 7.6.11, 12.2, 16; CISO should-fix deletion and scrub; database-105, billing-47..50, ops-51):
-- the erasure task table, the pseudonymised ledger archive, the erased-address tombstones that stop a second free grant,
-- consent records, and the column the sensitive-answer scrub stamps. Generated by drizzle-kit. Hand edits (each one):
--   1. this header;
--   2. applications.content_scrubbed_at is added IF NOT EXISTS: WP-42 adds the same spec column with the lifecycle set,
--      so whichever migration lands second is a no-op (its applications_scrub_due_idx on terminal_at stays WP-42's).
-- The four new tables are small, so their indexes build in the transaction. Grants: ops/provision-roles.sql.
CREATE TABLE "consent_records" (
	"user_id" text NOT NULL,
	"purpose" text NOT NULL,
	"version" text NOT NULL,
	"granted_at" timestamp with time zone DEFAULT now() NOT NULL,
	"withdrawn_at" timestamp with time zone,
	CONSTRAINT "consent_records_user_id_purpose_version_pk" PRIMARY KEY("user_id","purpose","version"),
	CONSTRAINT "consent_records_purpose_ck" CHECK (purpose ~ '^[a-z_]{1,40}$' AND char_length(version) BETWEEN 1 AND 40)
);
--> statement-breakpoint
CREATE TABLE "credit_ledger_archive" (
	"id" uuid PRIMARY KEY NOT NULL,
	"user_hash" text NOT NULL,
	"delta" integer NOT NULL,
	"reason" "credit_reason" NOT NULL,
	"application_id" uuid,
	"stripe_invoice_id" text,
	"note" text,
	"created_at" timestamp with time zone NOT NULL,
	"archived_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "credit_ledger_archive_hash_ck" CHECK (user_hash ~ '^[0-9a-f]{64}$')
);
